@using static sv_5380eea576a34ddab01e4a5bae24c6e8.Components.Pages.Apply.Apply

<div class="d-flex justify-content-between align-items-center mb-2">
    @for (int i = 0; i < _steps.Length; i++)
    {
        var stepNum = i + 1;
        var label = _steps[i];
        var isCurrent = stepNum == CurrentStep;
        var isCompleted = CompletedSteps.Contains(stepNum);
        var isClickable = isCompleted && !isCurrent;

        <div class="text-center flex-fill position-relative">
            <button class="btn rounded-circle d-inline-flex align-items-center justify-content-center @StepBadgeClass(isCurrent, isCompleted)"
                    style="width:40px;height:40px;font-size:.9rem;"
                    disabled="@(!isClickable)"
                    @onclick="() => OnStepClicked.InvokeAsync(stepNum)">
                @if (isCompleted && !isCurrent)
                {
                    <span>&#10003;</span>
                }
                else
                {
                    @stepNum
                }
            </button>
            <div class="small mt-1 @(isCurrent ? "fw-bold" : isCompleted ? "" : "text-muted")">@label</div>
        </div>

        @if (i < _steps.Length - 1)
        {
            <div class="flex-fill d-flex align-items-center" style="margin-top:-1.2rem;">
                <hr class="w-100 @(CompletedSteps.Contains(stepNum) ? "border-primary" : "")" />
            </div>
        }
    }
</div>

@code {
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly string[] _steps = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private string StepBadgeClass(bool isCurrent, bool isCompleted) =>
        isCurrent ? "btn-primary text-white"
        : isCompleted ? "btn-success text-white"
        : "btn-outline-secondary";
}

